import math

class SqrtDecomp:
    def __init__(self, a={{arr}}):
        self.a = a[:]; self.n = len(a)
        self.B = max(1, int(math.isqrt(self.n)))
        self.blocks = [sum(a[i:i+self.B]) for i in range(0, self.n, self.B)]
    def update(self, i, v):
        b = i // self.B
        self.blocks[b] += v - self.a[i]
        self.a[i] = v
    def query(self, l, r):
        s = 0; bl = l // self.B; br = r // self.B
        if bl == br:
            return sum(self.a[l:r+1])
        s += sum(self.a[l:(bl+1)*self.B])
        for b in range(bl+1, br): s += self.blocks[b]
        s += sum(self.a[br*self.B:r+1])
        return s
